<?php $counts=array('high'=>0,'medium'=>0,'low'=>0);foreach(($student_success_rows??array()) as $row)$counts[$row['risk_level']]++;?>
<div class="row"><div class="col-12"><div class="card"><div class="card-body"><h4 class="page-title">Student Success Analytics</h4><p class="text-muted mb-0">Transparent risk indicators from attendance, completed work, scores, trends, and recent engagement.</p></div></div></div></div>
<div class="row"><?php foreach(array('high'=>'High risk','medium'=>'Watch','low'=>'On track') as $key=>$label):?><div class="col-md-4"><div class="card"><div class="card-body"><small><?php echo $label;?></small><h3><?php echo $counts[$key];?></h3></div></div></div><?php endforeach;?></div>
<div class="row"><div class="col-12"><div class="card"><div class="card-body"><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Student</th><th>Teacher / Batch</th><th>Attendance</th><th>Work</th><th>Score</th><th>Engagement</th><th>Transparent reasons</th></tr></thead><tbody>
<?php foreach(($student_success_rows??array()) as $row):?><tr><td><?php echo html_escape(trim($row['first_name'].' '.$row['last_name']));?><br><small><?php echo html_escape($row['email']);?></small></td><td><?php echo html_escape(trim($row['tutor_first_name'].' '.$row['tutor_last_name']));?><br><small><?php echo html_escape($row['batch_title']);?></small></td><td><?php echo $row['metrics']['attendance'];?>%</td><td><?php echo $row['metrics']['assignment_completion'];?>%</td><td><?php echo $row['metrics']['score'];?>%</td><td><?php echo $row['metrics']['engagement'];?>%</td><td><?php if(!$row['risk']):?><span class="text-success">No watch indicators.</span><?php endif;?><?php foreach($row['risk'] as $reason):?><div><?php echo html_escape($reason['reason']);?></div><?php endforeach;?></td></tr><?php endforeach;?>
<?php if(empty($student_success_rows)):?><tr><td colspan="7" class="text-center text-muted">No active batch students found.</td></tr><?php endif;?></tbody></table></div></div></div></div></div>
